package com.example.starter.consent.dto;

import java.time.Instant;
import java.util.List;

import com.example.starter.consent.Purpose;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

/**
 * 委托创建请求：数据主体为代理人授予用途范围委托。
 *
 * @param delegateKey 委托键（幂等键），同键重放需参数指纹一致，失败不占键
 * @param subjectKey  数据主体标识（合成字符串）
 * @param agentKey    代理人标识（合成字符串），不得与主体相同
 * @param purposes    委托用途集合，规范化后非空；空集合返回 422
 * @param validFrom   有效期起（UTC，左闭）
 * @param validTo     有效期止（UTC，右开），必须晚于 validFrom
 */
public record DelegateCreateRequest(
        @NotBlank @Size(max = 128) String delegateKey,
        @NotBlank @Size(max = 128) String subjectKey,
        @NotBlank @Size(max = 128) String agentKey,
        @NotNull List<Purpose> purposes,
        @NotNull Instant validFrom,
        @NotNull Instant validTo) {
}

package com.example.starter.consent.dto;

import java.time.Instant;
import java.util.List;
import java.util.Map;

import com.example.starter.consent.DelegateStatus;
import com.example.starter.consent.Purpose;

/**
 * 委托响应：返回委托键、主体、代理、规范化用途集合、绑定的授权代次、UTC 有效期与版本。
 *
 * @param delegateKey     委托键
 * @param subjectKey      数据主体标识
 * @param agentKey        代理人标识
 * @param purposes        规范化用途集合（去重并按用途名排序）
 * @param epochs          各用途绑定的授权代次（用途 -> 代次）
 * @param validFrom       有效期起（UTC，左闭）
 * @param validTo         有效期止（UTC，右开）
 * @param delegateVersion 委托版本，从 1 开始
 * @param status          状态：ACTIVE 有效 / REVOKED 已撤销
 */
public record DelegateResponse(
        String delegateKey,
        String subjectKey,
        String agentKey,
        List<Purpose> purposes,
        Map<Purpose, Integer> epochs,
        Instant validFrom,
        Instant validTo,
        int delegateVersion,
        DelegateStatus status) {
}

package com.example.starter.consent.dto;

import java.time.Instant;

import jakarta.validation.constraints.Min;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Size;

/**
 * 批量续签项：按旧委托版本续签一份委托的有效期。
 *
 * @param delegateKey     委托键
 * @param expectedVersion 期望的旧委托版本，与当前版本不一致则整批不生效
 * @param validFrom       新有效期起（UTC，左闭）
 * @param validTo         新有效期止（UTC，右开），必须晚于 validFrom
 */
public record DelegateRenewItem(
        @NotBlank @Size(max = 128) String delegateKey,
        @NotNull @Min(1) Integer expectedVersion,
        @NotNull Instant validFrom,
        @NotNull Instant validTo) {
}

package com.example.starter.consent.dto;

import java.util.List;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.Size;

/**
 * 批量续签请求：先校验每份旧委托版本，任一冲突整批不生效。
 *
 * @param requestId 幂等请求标识
 * @param items     续签项列表，按委托键排序后规范化
 */
public record DelegateRenewRequest(
        @NotBlank @Size(max = 128) String requestId,
        @NotEmpty List<@Valid DelegateRenewItem> items) {
}

package com.example.starter.consent.dto;

import java.util.List;

/**
 * 批量续签响应：整批生效后的委托列表（新版本）。
 *
 * @param renewed 续签后的委托列表，按委托键排序
 */
public record DelegateRenewResponse(List<DelegateResponse> renewed) {
}

package com.example.starter.consent.dto;

import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Size;

/**
 * 委托撤销请求：撤销只影响后续查询，已生成查询快照固化委托与授权版本。
 *
 * @param requestId   幂等请求标识
 * @param delegateKey 待撤销的委托键
 */
public record DelegateRevokeRequest(
        @NotBlank @Size(max = 128) String requestId,
        @NotBlank @Size(max = 128) String delegateKey) {
}

package com.example.starter.consent.dto;

import com.example.starter.consent.DelegateStatus;

/**
 * 委托状态响应：返回委托键、当前版本与状态。
 *
 * @param delegateKey     委托键
 * @param delegateVersion 当前委托版本
 * @param status          状态：ACTIVE 有效 / REVOKED 已撤销
 */
public record DelegateStatusResponse(
        String delegateKey,
        int delegateVersion,
        DelegateStatus status) {
}

