 * @param validTo         有效期止（UTC，右开）
 */
public record DelegateVersionView(
        int delegateVersion,
        List<Purpose> purposes,
        Map<Purpose, Integer> epochs,
        Instant validFrom,
        Instant validTo) {
}

package com.example.starter.consent.dto;

import java.util.List;

import com.example.starter.consent.DelegateStatus;

/**
 * 委托历史响应：委托当前状态与全部版本，按版本升序。
 *
 * @param delegateKey    委托键
 * @param subjectKey     数据主体标识
 * @param agentKey       代理人标识
 * @param status         状态：ACTIVE 有效 / REVOKED 已撤销
 * @param currentVersion 当前委托版本
 * @param versions       全部委托版本，按版本升序
 */
public record DelegateHistoryResponse(
        String delegateKey,
        String subjectKey,
        String agentKey,
        DelegateStatus status,
        int currentVersion,
        List<DelegateVersionView> versions) {
}

package com.example.starter.consent.dto;

import java.util.List;

import com.example.starter.consent.Purpose;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.NotEmpty;
import jakarta.validation.constraints.Size;

/**
 * 代理批量查询请求：代理人对多个主体发起批量查询，
 * 每个主体的当前授权代次均须有该代理有效委托且覆盖请求用途。
 *
 * @param requestId 幂等请求标识，成功批次生成快照
 * @param agentKey  代理人标识（合成字符串）
 * @param subjects  主体标识列表，规范化去重后按标识排序
 * @param purposes  请求用途集合，规范化去重后按用途名排序
 */
public record DelegateQueryRequest(
        @NotBlank @Size(max = 128) String requestId,
        @NotBlank @Size(max = 128) String agentKey,
        @NotEmpty List<@NotBlank @Size(max = 128) String> subjects,
        @NotEmpty List<Purpose> purposes) {
}

package com.example.starter.consent.dto;

import com.example.starter.consent.Purpose;

/**
 * 批次查询返回的记录视图。
 *
 * @param purpose   用途：RESEARCH 研究 / PERSONALIZATION 个性化
 * @param epoch     记录所属授权代次
 * @param recordKey 记录键
 * @param payload   记录内容（合成字符串）
 */
public record DelegateRecordView(
        Purpose purpose,
        int epoch,
        String recordKey,
        String payload) {
}

package com.example.starter.consent.dto;

import java.util.List;
import java.util.Map;

import com.example.starter.consent.Purpose;

/**
 * 批次查询中单个主体的结果：固化命中的委托与授权版本。
 *
 * @param subjectKey      主体标识
 * @param delegateKey     命中的委托键
 * @param delegateVersion 固化的委托版本
 * @param epochs          固化的授权代次（用途 -> 代次）
 * @param records         当前代次下的记录列表，按用途名与记录键排序
 */
public record DelegateSubjectResult(
        String subjectKey,
        String delegateKey,
        int delegateVersion,
        Map<Purpose, Integer> epochs,
        List<DelegateRecordView> records) {
}

package com.example.starter.consent.dto;

import java.util.List;

import com.example.starter.consent.Purpose;

/**
 * 代理批量查询响应：全部主体通过校验后返回数据并生成快照。
 *
 * @param queryId  批次查询标识（即查询请求幂等键）
 * @param agentKey 代理人标识
 * @param purposes 规范化请求用途集合
 * @param subjects 各主体结果，按主体标识排序
 */
public record DelegateQueryResponse(
        String queryId,
        String agentKey,
        List<Purpose> purposes,
        List<DelegateSubjectResult> subjects) {
}

